#include "../src/transport.hpp"
#include <iostream>
int main(){std::string line;while(std::getline(std::cin,line)){try{auto j=vpn::json_parse(line);vpn::Json out=vpn::Json::obj();auto op=j.at("op").scalar();if(op=="native-reason"){auto status=uint32_t(std::stoull(j.at("status").scalar()));out["reason_code"]=vpn::Json(vpn::native_tls_reason(status,"TLS_HANDSHAKE_VERIFY"));out["native_status"]=vpn::Json::integer(status);}else if(op=="headers"){auto h=vpn::http_headers(j.at("text").scalar());out["cookies"]=vpn::Json::arr();for(const auto& v:h.set_cookies)out["cookies"].array.emplace_back(v);out["connection"]=vpn::Json(vpn::option(h,{"connection"}));out["fields"]=vpn::Json::arr();for(const auto& field:h.fields){auto item=vpn::Json::arr();item.array.emplace_back(field.first);item.array.emplace_back(field.second);out["fields"].array.push_back(item);}}else if(op=="nonce"){vpn::Bytes nonce(12,255);vpn::advance_nonce(nonce);}else{vpn::Config c;vpn::parse_uri(c,j.at("uri").scalar());if(op=="decode"){vpn::Protocol p(c);(void)p.open(vpn::Bytes{1,127,0,0,1,1,187});auto data=vpn::b64_decode(j.at("data").scalar());(void)p.decode(data);}else{out=vpn::inspection(c);out["selected_alpn"]=vpn::Json::arr();for(const auto& v:vpn::tls_protocols(c))out["selected_alpn"].array.emplace_back(v);out["password_hash"]=vpn::Json(c.password_hash);out["path"]=vpn::Json(c.path);out["original_flow"]=vpn::Json(vpn::option(c.original_options,{"flow"}));out["original_type"]=vpn::Json(vpn::option(c.original_options,{"type"}));}}std::cout<<vpn::json_dump(out)<<'\n';}catch(const std::exception& e){vpn::Json out=vpn::Json::obj();auto f=dynamic_cast<const vpn::Failure*>(&e);out["error"]=vpn::Json(e.what());out["reason_code"]=vpn::Json(f?f->code:"");std::cout<<vpn::json_dump(out)<<'\n';}}}
